const req=$input.first().json||{};
const body=req.body||req;
const text=String(body.text||'').trim();
const explicitInvoice=body.invoice_reference==null?'':String(body.invoice_reference).trim();
const explicitTax=body.claimed_tax_id==null?'':String(body.claimed_tax_id).replace(/\D/g,'');
const invoiceMatch=text.match(/(?:FACTURA|INVOICE)\s*[:=#-]?\s*([A-Z0-9-]{4,120})/i);
const taxMatch=text.match(/(?:RUC|TAX)\s*[:=#-]?\s*(\d{8,20})/i);
const providerMessageId=String(body.provider_message_id||body.message_id||'').trim();
const subject=String(body.subject||body.sender_id||'').trim();
const channel=String(body.channel||'whatsapp').trim().toLowerCase();
const tenantId=String(body.tenant_id||'30000000-0000-0000-0000-000000000000').trim();
const traceId=String(body.trace_id||providerMessageId).trim();
if(!providerMessageId) throw new Error('GATE6_PROVIDER_MESSAGE_ID_REQUIRED');
if(!subject) throw new Error('GATE6_SUBJECT_REQUIRED');
if(!text) throw new Error('GATE6_TEXT_REQUIRED');
return [{json:{
  tenant_id:tenantId,
  channel,
  subject,
  provider_message_id:providerMessageId,
  text,
  invoice_reference:explicitInvoice||(invoiceMatch?.[1]||null),
  claimed_tax_id:explicitTax||(taxMatch?.[1]||null),
  trace_id:traceId
}}];

const j=$input.first().json||{};
const allowed=new Set(['FOUND','DUPLICATE','AUTH_REQUIRED','VERIFICATION_REQUIRED','NOT_FOUND_OR_NOT_AUTHORIZED','NEEDS_DISAMBIGUATION']);
if(!allowed.has(j.decision)) throw new Error('GATE6_UNEXPECTED_DECISION');
if(j.channel_delivery!=='disabled') throw new Error('GATE6_OUTBOUND_MUST_BE_DISABLED');
if(j.decision!=='FOUND'){
  for(const k of ['company_code','fi_document_number','snapshot_id']){
    if(j[k]!==undefined&&j[k]!==null) throw new Error('GATE6_DENIED_RESPONSE_LEAK:'+k);
  }
}
return [{json:{...j,gate6Assertion:true}}];
